<?php $people=array_column($demo['profiles'],null,'id');$media=array_column($demo['media'],null,'id');$who=(string)($_GET['profile']??''); ?>
<section class="form-panel" id="demo-feed"><p class="notice model-demo-banner"><strong>סביבת הדגמה למשקיעים</strong> — הדמויות והפעילות מדומות; המקומות מקושרים לקטלוג. אין כאן נתוני שימוש אמיתיים.</p><h2>פיד ההדגמה</h2><nav><a href="?demo=<?=e($demo['id'])?>#demo-feed"><?=e(uiMessage('admin.release.60'))?></a><?php foreach($people as $person):?> · <a href="?demo=<?=e($demo['id'])?>&amp;profile=<?=e($person['id'])?>#demo-feed"><?=e($person['name'])?></a><?php endforeach?></nav>
<?php foreach($demo['posts'] as $post):if($who&&$who!==$post['author_id'])continue;$person=$people[$post['author_id']];?><article class="network-card network-form model-demo-post" lang="<?=e($post['language'])?>" dir="<?=$post['language']==='he'?'rtl':'ltr'?>"><header class="network-author"><a href="?demo=<?=e($demo['id'])?>&amp;profile=<?=e($person['id'])?>#demo-feed"><?=e($person['name'])?></a><span class="network-avatar"><?php if(isset($media[$person['avatar_media_id']??''])):?><img alt="" src="?demo_image=<?=e($media[$person['avatar_media_id']]['hash'])?>"><?php else:?><?=e(mb_substr($person['name'],0,1))?><?php endif?></span></header><p><?=e($person['bio'])?></p><h3><?=e($post['title'])?></h3><p><?=nl2br(e($post['body']))?></p><?php foreach($post['media_ids'] as $id):?><img class="model-demo-photo" src="?demo_image=<?=e($media[$id]['hash'])?>" alt="<?=e($post['title'])?>"><?php endforeach?><ol><?php foreach($post['place_ids'] as $id):$place=$demo['catalogue'][$id];?><li><a href="<?=e($place['site_url'])?>"><?=e($place['title'])?></a> · <?=e($place['cost'])?></li><?php endforeach?></ol><p>מצב הדגמה: <?=e($post['moderation_state'])?> · לייקים לדוגמה: <?=(int)$post['demo_likes']?><?php if($post['demo_rating']!==null):?> · דירוג פוסט לדוגמה: <?=e((string)$post['demo_rating'])?> ★<?php endif?></p><details><summary>תגובות לדוגמה</summary><?php foreach($demo['comments'] as $comment)if($comment['post_id']===$post['id']):?><p><strong><?=e($people[$comment['author_id']]['name'])?></strong>: <?=e($comment['body'])?></p><?php endif?></details></article><?php endforeach?></section>
